/*---
description: NFKC agrees with Node for every code point U+010000 through U+01FFFF.
features: [ts-unicode-normalization, ts-strings, ts-iteration, ts-arrays, ts-unicode-exhaustive]
---*/
// Generated by tooling/unicode-cases/normalization.ts; Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [3753525473, 3198818757, 3748979141, 3662897605, 418361797, 1223811525, 2919678405, 3661109701, 3498140101, 3388834245, 1684883909, 2771642821, 205892197, 4117756647, 1900481714, 2701466993];
const blocks = ["NFKC U+010000-U+010FFF", "NFKC U+011000-U+011FFF", "NFKC U+012000-U+012FFF", "NFKC U+013000-U+013FFF", "NFKC U+014000-U+014FFF", "NFKC U+015000-U+015FFF", "NFKC U+016000-U+016FFF", "NFKC U+017000-U+017FFF", "NFKC U+018000-U+018FFF", "NFKC U+019000-U+019FFF", "NFKC U+01A000-U+01AFFF", "NFKC U+01B000-U+01BFFF", "NFKC U+01C000-U+01CFFF", "NFKC U+01D000-U+01DFFF", "NFKC U+01E000-U+01EFFF", "NFKC U+01F000-U+01FFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 65536 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFKC");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
